  // Observable's default filter anchors each term to a word start, so mid-word
  // fragments ("שית" in "עששית") return nothing. Match plain substrings instead.
  filter: (query) =&gt; {
    const terms = `${query}`.toLowerCase().split(/\s+/g).filter(t =&gt; t);
    return (d) =&gt; terms.every(t =&gt;
      Object.values(d).some(v =&gt; `${v}`.toLowerCase().includes(t)));
  }
})







