// Row ids have to stay unique even after rows are deleted, so keep a
// monotonic counter on the container rather than counting the rows present.
function nextRowId (container) {
    const node = d3.select(container).node()
    const next = (Number(node.dataset.rowSeq) || 1) + 1
    node.dataset.rowSeq = String(next)
    return next
}

